{
  "kind": "periodic",
  "schema": {
    "$defs": {
      "Circle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "circle",
            "default": "circle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Circle",
        "type": "object"
      },
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "Ellipse": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "ellipse",
            "default": "ellipse",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "semi_axes_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Semi Axes Nm",
            "type": "array"
          },
          "angle_deg": {
            "default": 0.0,
            "title": "Angle Deg",
            "type": "number"
          }
        },
        "required": [
          "semi_axes_nm"
        ],
        "title": "Ellipse",
        "type": "object"
      },
      "Incidence": {
        "additionalProperties": false,
        "properties": {
          "theta_deg": {
            "default": 0.0,
            "title": "Theta Deg",
            "type": "number"
          },
          "phi_deg": {
            "default": 0.0,
            "title": "Phi Deg",
            "type": "number"
          },
          "polarizations": {
            "default": [
              "s",
              "p"
            ],
            "items": {
              "enum": [
                "s",
                "p"
              ],
              "type": "string"
            },
            "title": "Polarizations",
            "type": "array"
          }
        },
        "title": "Incidence",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "PatternedLayer": {
        "additionalProperties": false,
        "properties": {
          "thickness_nm": {
            "exclusiveMinimum": 0,
            "title": "Thickness Nm",
            "type": "number"
          },
          "background": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Background"
          },
          "shapes": {
            "description": "Inclusions in one unit cell (xy).",
            "items": {
              "$ref": "#/$defs/Structure2D"
            },
            "title": "Shapes",
            "type": "array"
          }
        },
        "required": [
          "thickness_nm",
          "background"
        ],
        "title": "PatternedLayer",
        "type": "object"
      },
      "Polygon": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "polygon",
            "default": "polygon",
            "title": "Kind",
            "type": "string"
          },
          "vertices_nm": {
            "items": {
              "maxItems": 2,
              "minItems": 2,
              "prefixItems": [
                {
                  "type": "number"
                },
                {
                  "type": "number"
                }
              ],
              "type": "array"
            },
            "minItems": 3,
            "title": "Vertices Nm",
            "type": "array"
          }
        },
        "required": [
          "vertices_nm"
        ],
        "title": "Polygon",
        "type": "object"
      },
      "Rectangle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "rectangle",
            "default": "rectangle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "size_nm"
        ],
        "title": "Rectangle",
        "type": "object"
      },
      "Structure2D": {
        "additionalProperties": false,
        "properties": {
          "name": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Name"
          },
          "profile": {
            "discriminator": {
              "mapping": {
                "circle": "#/$defs/Circle",
                "ellipse": "#/$defs/Ellipse",
                "polygon": "#/$defs/Polygon",
                "rectangle": "#/$defs/Rectangle"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Rectangle"
              },
              {
                "$ref": "#/$defs/Circle"
              },
              {
                "$ref": "#/$defs/Ellipse"
              },
              {
                "$ref": "#/$defs/Polygon"
              }
            ],
            "title": "Profile"
          },
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          }
        },
        "required": [
          "profile",
          "material"
        ],
        "title": "Structure2D",
        "type": "object"
      },
      "Tabulated": {
        "additionalProperties": false,
        "description": "Tabulated n, k data, linearly interpolated (no extrapolation).",
        "properties": {
          "kind": {
            "const": "tabulated",
            "default": "tabulated",
            "title": "Kind",
            "type": "string"
          },
          "wavelength_nm": {
            "items": {
              "type": "number"
            },
            "title": "Wavelength Nm",
            "type": "array"
          },
          "n_real": {
            "items": {
              "type": "number"
            },
            "title": "N Real",
            "type": "array"
          },
          "n_imag": {
            "items": {
              "type": "number"
            },
            "title": "N Imag",
            "type": "array"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Citation / provenance of the data.",
            "title": "Source"
          }
        },
        "required": [
          "wavelength_nm",
          "n_real",
          "n_imag"
        ],
        "title": "Tabulated",
        "type": "object"
      },
      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "A 1D/2D-periodic stack of patterned layers under plane-wave illumination.",
    "properties": {
      "kind": {
        "const": "periodic",
        "default": "periodic",
        "title": "Kind",
        "type": "string"
      },
      "lattice_a1_nm": {
        "maxItems": 2,
        "minItems": 2,
        "prefixItems": [
          {
            "type": "number"
          },
          {
            "type": "number"
          }
        ],
        "title": "Lattice A1 Nm",
        "type": "array"
      },
      "lattice_a2_nm": {
        "anyOf": [
          {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "description": "None for 1D gratings: periodic along a1, invariant perpendicular to it; shapes are sampled along the line through the origin in the a1 direction.",
        "title": "Lattice A2 Nm"
      },
      "superstrate": {
        "discriminator": {
          "mapping": {
            "constant_index": "#/$defs/ConstantIndex",
            "constant_permittivity": "#/$defs/ConstantPermittivity",
            "drude": "#/$defs/Drude",
            "drude_lorentz": "#/$defs/DrudeLorentz",
            "library": "#/$defs/LibraryMaterial",
            "tabulated": "#/$defs/Tabulated"
          },
          "propertyName": "kind"
        },
        "oneOf": [
          {
            "$ref": "#/$defs/ConstantIndex"
          },
          {
            "$ref": "#/$defs/ConstantPermittivity"
          },
          {
            "$ref": "#/$defs/Drude"
          },
          {
            "$ref": "#/$defs/DrudeLorentz"
          },
          {
            "$ref": "#/$defs/Tabulated"
          },
          {
            "$ref": "#/$defs/LibraryMaterial"
          }
        ],
        "title": "Superstrate"
      },
      "layers": {
        "description": "From the superstrate side to the substrate side.",
        "items": {
          "$ref": "#/$defs/PatternedLayer"
        },
        "minItems": 1,
        "title": "Layers",
        "type": "array"
      },
      "substrate": {
        "discriminator": {
          "mapping": {
            "constant_index": "#/$defs/ConstantIndex",
            "constant_permittivity": "#/$defs/ConstantPermittivity",
            "drude": "#/$defs/Drude",
            "drude_lorentz": "#/$defs/DrudeLorentz",
            "library": "#/$defs/LibraryMaterial",
            "tabulated": "#/$defs/Tabulated"
          },
          "propertyName": "kind"
        },
        "oneOf": [
          {
            "$ref": "#/$defs/ConstantIndex"
          },
          {
            "$ref": "#/$defs/ConstantPermittivity"
          },
          {
            "$ref": "#/$defs/Drude"
          },
          {
            "$ref": "#/$defs/DrudeLorentz"
          },
          {
            "$ref": "#/$defs/Tabulated"
          },
          {
            "$ref": "#/$defs/LibraryMaterial"
          }
        ],
        "title": "Substrate"
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
            "$ref": "#/$defs/WavelengthRange"
          }
        ],
        "title": "Wavelengths"
      },
      "incidence": {
        "$ref": "#/$defs/Incidence",
        "default": {
          "theta_deg": 0.0,
          "phi_deg": 0.0,
          "polarizations": [
            "s",
            "p"
          ]
        }
      },
      "options": {
        "additionalProperties": {
          "additionalProperties": true,
          "type": "object"
        },
        "title": "Options",
        "type": "object"
      }
    },
    "required": [
      "lattice_a1_nm",
      "superstrate",
      "layers",
      "substrate",
      "wavelengths"
    ],
    "title": "PeriodicProblem",
    "type": "object"
  },
  "conventions": "Lightsmith conventions (fixed; changing them needs a schema version bump):\n- Lengths in nm. Wavelengths are vacuum wavelengths in nm.\n- Time dependence exp(-i omega t): absorbing materials have Im(eps) > 0 and Im(n) > 0.\n- Cross sections in nm^2; efficiencies Q = C / (pi r_eq^2), r_eq = volume-equivalent radius of all particles.\n- layer_stack / periodic: layers listed from the superstrate (incidence side) to the substrate; light travels +z.\n  R is measured in the superstrate, T in the substrate.\n- mode: cross-section in the xy plane, propagation along +z.\n- device: ports are planes whose normal is the axis where size_nm is zero; direction is into the device.\n- problem.options[<method or backend name>] holds solver options, validated by that backend.\n- Materials: {\"kind\": \"constant_index\", \"n_real\": .., \"n_imag\": ..}, {\"kind\": \"library\", \"name\": \"Au\"},\n  drude, drude_lorentz, tabulated, constant_permittivity. FDTD needs dispersive models (fit_drude_lorentz).\n- Results carry provenance and warnings: read the warnings before trusting the numbers.\n",
  "backends": [
    {
      "name": "lightsmith-rcwa",
      "method": "rcwa",
      "available": true,
      "gpu": true,
      "auto_rank": 0
    },
    {
      "name": "lightsmith-fdtd",
      "method": "fdtd",
      "available": true,
      "gpu": true,
      "auto_rank": 2
    }
  ],
  "example": {
    "kind": "periodic",
    "lattice_a1_nm": [
      400,
      0
    ],
    "lattice_a2_nm": [
      0,
      400
    ],
    "superstrate": {
      "kind": "constant_index",
      "n_real": 1.0
    },
    "layers": [
      {
        "thickness_nm": 150,
        "background": {
          "kind": "constant_index",
          "n_real": 2.0
        },
        "shapes": [
          {
            "profile": {
              "kind": "circle",
              "radius_nm": 100
            },
            "material": {
              "kind": "constant_index",
              "n_real": 1.0
            }
          }
        ]
      }
    ],
    "substrate": {
      "kind": "constant_index",
      "n_real": 1.45
    },
    "wavelengths": [
      560,
      600,
      640
    ],
    "incidence": {
      "polarizations": [
        "s"
      ]
    },
    "options": {
      "rcwa": {
        "harmonics": 3
      }
    }
  }
}

